28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const PROCESSING_FEE = 5;
38	
39	const WHOLE_PERCENT = 100;
40	
41	/**
42	 * Surcharges multiply before dividing, so the arithmetic stays exact.
43	 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
44	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
45	 * instead of 115 G.
46	 */
47	const addSurcharge = (amount: number, surchargePercent: number): number =>
48	  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;
49	
50	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
51	
52	/** All rounding is in the MHPCO's favor — always up. */
53	const roundInMHPCOsFavor = Math.ceil;
54	
55	const BUILDING_BLOCK_SIZE = 3;
56	const BUILDING_BLOCK_PREMIUM = 60;
57	
58	const allAlike = (items: InsuredItem[]): boolean =>
59	  items.every((item) => item.type === items[0].type);
60	
61	/**
62	 * How many flat-rate blocks this list forms. A mixed list forms none — only
63	 * alike items group — and so does any list too short to fill one block.
64	 */
65	const countCompleteBlocks = (items: InsuredItem[]): number =>
66	  allAlike(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
67	
68	const sumIndividually = (items: InsuredItem[]): number =>
69	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
70	
71	/**
72	 * Prices an item list: alike items are grouped into building blocks sold at a
73	 * flat rate, and whatever is left over is the sum of its items' base premiums.
74	 */
75	const priceItems = (items: InsuredItem[]): number => {
76	  const blocks = countCompleteBlocks(items);
77	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
78	
79	  return blocks * BUILDING_BLOCK_PREMIUM + sumIndividually(leftovers);
80	};
81	
82	/**
83	 * The premium pipeline, in the order the spec states it: price the items,
84	 * apply surcharges, round, then add the processing fee last.
85	 */
86	const quotePremium = (step: Step): QuoteResult => {
87	  const basePremium = priceItems(step.items ?? []);
88	  const surcharged = addSurcharge(
89	    basePremium,
90	    FIRST_INSURANCE_SURCHARGE_PERCENT,
91	  );
92	
93	  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
94	};
95	
96	export const runScenario = (scenario: Scenario): ScenarioResults => ({
97	  results: scenario.steps.map(quotePremium),
98	});
